import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Texture,
    Color
  } = THREE;

  const colors =
    config.intent?.visualSpec?.colors ?? {
      ink: '#16161d',
      paper: '#e8ecf2',
      accent: '#ff2a38',
      surface: '#0b0b10'
    };

  const root = new Group();
  root.name = config.id ?? 'collection-card-3';

  const region =
    config.atlasRegion ??
    config.atlas?.sourceRect ?? {
      x: 0,
      y: 0,
      width: 512,
      height: 320
    };

  const aspect = region.width / region.height;
  const cardWidth = 2.6;
  const cardHeight = cardWidth / aspect;
  const timelines = [];
  const ownedMaterials = [];
  const ownedGeometries = [];
  const loadedTextures = [];
  let disposed = false;

  const backingGeometry = new BoxGeometry(
    cardWidth + 0.1,
    cardHeight + 0.1,
    0.08
  );
  const backingMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.surface)
  });
  const backing = new Mesh(backingGeometry, backingMaterial);
  backing.position.z = -0.055;
  root.add(backing);
  ownedGeometries.push(backingGeometry);
  ownedMaterials.push(backingMaterial);

  const imageGeometry = new PlaneGeometry(cardWidth, cardHeight);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.paper),
    transparent: false
  });
  const image = new Mesh(imageGeometry, imageMaterial);
  image.position.z = 0.01;
  root.add(image);
  ownedGeometries.push(imageGeometry);
  ownedMaterials.push(imageMaterial);

  const accentGeometry = new BoxGeometry(cardWidth * 0.22, 0.025, 0.018);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.accent)
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(
    -cardWidth * 0.5 + cardWidth * 0.13,
    -cardHeight * 0.5 - 0.075,
    0.02
  );
  root.add(accent);
  ownedGeometries.push(accentGeometry);
  ownedMaterials.push(accentMaterial);

  const edgeGeometry = new BoxGeometry(0.018, cardHeight + 0.1, 0.018);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.ink)
  });
  const leftEdge = new Mesh(edgeGeometry, edgeMaterial);
  const rightEdge = new Mesh(edgeGeometry, edgeMaterial);
  leftEdge.position.set(-cardWidth * 0.5 - 0.055, 0, 0.018);
  rightEdge.position.set(cardWidth * 0.5 + 0.055, 0, 0.018);
  root.add(leftEdge, rightEdge);
  ownedGeometries.push(edgeGeometry);
  ownedMaterials.push(edgeMaterial);

  root.onBeforeRender = (_renderer, _scene, camera) => {
    if (!disposed && camera) root.lookAt(camera.position);
  };

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed || !texture) return;

      loadedTextures.push(texture);
      if ('colorSpace' in texture && THREE.SRGBColorSpace) {
        texture.colorSpace = THREE.SRGBColorSpace;
      }

      const sourceWidth =
        texture.image?.width ??
        config.atlas?.width ??
        region.width;
      const sourceHeight =
        texture.image?.height ??
        config.atlas?.height ??
        region.height;

      texture.wrapS = THREE.ClampToEdgeWrapping;
      texture.wrapT = THREE.ClampToEdgeWrapping;
      texture.repeat.set(
        region.width / sourceWidth,
        region.height / sourceHeight
      );
      texture.offset.set(
        region.x / sourceWidth,
        1 - (region.y + region.height) / sourceHeight
      );
      texture.needsUpdate = true;

      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    root.traverse((object) => {
      if (object.onBeforeRender) object.onBeforeRender = null;
    });

    for (const geometry of ownedGeometries) geometry.dispose();
    for (const material of ownedMaterials) material.dispose();

    for (const texture of loadedTextures) {
      if (texture?.dispose) texture.dispose();
    }

    root.clear();
  };

  return root;
}
